    var log2Depth = depthOrLogDepth * czm_log2FarDepthFromNearPlusOne;
    var depthFromNear = pow(2.0, log2Depth) - 1.0;
    var depthFromCamera = depthFromNear + near;
    var screenCoord = vec4<32>(screenCoordinateXY, far * (1.0 - near / depthFromCamera) / (far - near), 1.0);
