            nextCascadeMatrix = shadowMap_cascadeMatrices[1];
            cascadeLightSizeUVAndDepthCorrection = shadowMap_cascadeLightSizeUVAndDepthCorrection[0];
            nextCascadeLightSizeUVAndDepthCorrection = shadowMap_cascadeLightSizeUVAndDepthCorrection[1];
            csmBlend = weights.y > 0.0;
            diffRatio = (depth - shadowMap_cascadeSplits[0].y) / (shadowMap_cascadeSplits[1].x - shadowMap_cascadeSplits[0].y);
