            shadowParameters.texCoords = nextShadowPosition.xy;
            shadowParameters.depth = nextShadowPosition.z;
            shadowParameters.shadowMapIndex = shadowMapIndex + 1.0;
            shadowParameters.lightSizeUVCorrection = nextCascadeLightSizeUVAndDepthCorrection.xy;
            shadowParameters.depthCorrection = nextCascadeLightSizeUVAndDepthCorrection.z;
